mapper.select:
select m.id, m.music_name as musicName, m.album_id as albumId, m.musician_id as musicianId, m.duration, m.cover_url as coverUrl, m.is_vip as isVip, m.status, IFNULL(u.stage_name, '未知音乐人') AS musicianName, IFNULL(a.album_name, '未知专辑') AS albumName, l.updated_time as updatedTime from music as m left join musician u on m.musician_id = u.id left join album a on m.album_id = a.id left join like_record l on m.id = l.target_id where l.user_id = #{userId} and l.target_type = 1 and l.is_canceled = 0
and m.id < #{lastId}
GROUP BY m.id order by l.updated_time desc limit #{pageSize}
